<template>
  <LabToolPage :meta="meta">
    <section class="lab-workspace dev-workspace" aria-labelledby="dev-workspace-title">
      <div class="lab-panel dev-controls-panel">
        <div class="lab-panel-heading"><div><p class="card-kicker">01 · INPUT</p><h2 id="dev-workspace-title">输入与处理</h2></div><span class="lab-step">本地</span></div>
        <div class="lab-tab-list" role="tablist" aria-label="开发者便签功能"><button v-for="item in tabs" :key="item.id" class="lab-tab" :class="{ active: activeTab === item.id }" type="button" role="tab" :aria-selected="activeTab === item.id" @click="activeTab = item.id">{{ item.label }}</button></div>
        <template v-if="activeTab === 'json'"><label for="dev-json">JSON 输入</label><textarea id="dev-json" v-model="jsonInput" class="lab-textarea dev-textarea" maxlength="200000" spellcheck="false" placeholder="{ &quot;hello&quot;: &quot;Levi Lab&quot; }"></textarea><div class="lab-button-row"><button class="lab-button is-primary" type="button" :disabled="jsonTooLong" @click="formatJson">格式化</button><button class="lab-button is-secondary" type="button" :disabled="jsonTooLong" @click="compactJson">压缩</button></div><p v-if="jsonError" class="lab-message is-error" role="alert">{{ jsonError }}</p></template>
        <template v-else-if="activeTab === 'timestamp'"><div class="lab-setting-group dev-inline-group"><label>输入时间<input v-model="timestampInput" class="lab-input" placeholder="当前时间戳或 2026-08-24 12:00"></label><label>单位<select v-model="timestampUnit" class="lab-select"><option value="auto">自动识别</option><option value="seconds">秒</option><option value="milliseconds">毫秒</option></select></label></div><div class="lab-button-row"><button class="lab-button is-primary" type="button" @click="convertTimestamp">转换时间</button><button class="lab-button is-secondary" type="button" @click="useNow">使用当前时间</button></div><p v-if="timestampError" class="lab-message is-error" role="alert">{{ timestampError }}</p></template>
        <template v-else-if="activeTab === 'url'"><label for="dev-url">URL</label><textarea id="dev-url" v-model="urlInput" class="lab-textarea dev-textarea" rows="4" maxlength="200000" placeholder="https://example.com/search?q=手账&amp;page=1"></textarea><div class="lab-button-row"><button class="lab-button is-primary" type="button" @click="encodeUrl">编码</button><button class="lab-button is-secondary" type="button" @click="decodeUrl">解码</button><button class="lab-button is-secondary" type="button" @click="parseUrl">解析参数</button></div><p v-if="urlError" class="lab-message is-error" role="alert">{{ urlError }}</p></template>
        <template v-else-if="activeTab === 'base64'"><label for="dev-base64">文本或 Base64</label><textarea id="dev-base64" v-model="base64Input" class="lab-textarea dev-textarea" maxlength="200000" spellcheck="false" placeholder="UTF-8 文本"></textarea><div class="lab-button-row"><button class="lab-button is-primary" type="button" @click="encodeBase64">UTF-8 编码</button><button class="lab-button is-secondary" type="button" @click="decodeBase64">Base64 解码</button></div><p class="lab-hint">Base64 只是编码，不是加密；不处理大文件。</p><p v-if="base64Error" class="lab-message is-error" role="alert">{{ base64Error }}</p></template>
        <template v-else><label for="dev-text">文本</label><textarea id="dev-text" v-model="textInput" class="lab-textarea dev-textarea" maxlength="200000" placeholder="粘贴一段文字，看看它有多长"></textarea><p class="lab-hint">输入不会保存到 localStorage。超过 200,000 个字符时暂停实时统计。</p></template>
        <p class="lab-privacy-line">所有便签逻辑在当前浏览器运行，不执行输入内容，也不保存输入。</p>
      </div>
      <div class="lab-panel dev-result-panel" :class="`is-${activeTab}`" aria-live="polite">
        <div class="lab-panel-heading"><div><p class="card-kicker">02 · RESULT</p><h2>{{ activeTab === 'text' ? '文本统计' : '处理结果' }}</h2></div><span v-if="activeTab === 'text'" class="lab-status is-success">实时</span></div>
        <div v-if="tooLong" class="query-notice is-warning"><strong>输入超过 200,000 个字符</strong><span>请缩小输入后再继续处理。</span></div>
        <template v-else-if="activeTab === 'json'"><pre class="dev-output"><code>{{ jsonOutput || '格式化或压缩结果会显示在这里。' }}</code></pre><button class="lab-button is-secondary lab-full-button" type="button" :disabled="!jsonOutput" @click="copyResult(jsonOutput)">{{ copied ? '已复制结果' : '复制结果' }}</button></template>
        <template v-else-if="activeTab === 'timestamp'"><div class="dev-result-list"><div><small>本地时间</small><strong>{{ timestampResult.local || '等待转换' }}</strong></div><div><small>UTC</small><strong>{{ timestampResult.utc || '—' }}</strong></div><div><small>时间戳（秒）</small><strong>{{ timestampResult.seconds || '—' }}</strong></div><div><small>当前时区</small><strong>{{ timestampResult.timezone }}</strong></div></div><button class="lab-button is-secondary lab-full-button" type="button" :disabled="!timestampResult.seconds" @click="copyResult(timestampResult.seconds)">{{ copied ? '已复制时间戳' : '复制时间戳' }}</button></template>
        <template v-else-if="activeTab === 'url'"><pre class="dev-output"><code>{{ urlOutput || '编码、解码或解析结果会显示在这里。' }}</code></pre><div v-if="urlParams.length" class="url-param-list"><div v-for="param in urlParams" :key="param.key + param.value"><code>{{ param.key }}</code><span>{{ param.value }}</span><button class="lab-text-button" type="button" @click="copyResult(param.value)">复制</button></div></div><button class="lab-button is-secondary lab-full-button" type="button" :disabled="!urlOutput" @click="copyResult(urlOutput)">{{ copied ? '已复制结果' : '复制结果' }}</button></template>
        <template v-else-if="activeTab === 'base64'"><pre class="dev-output"><code>{{ base64Output || 'Base64 结果会显示在这里。' }}</code></pre><button class="lab-button is-secondary lab-full-button" type="button" :disabled="!base64Output" @click="copyResult(base64Output)">{{ copied ? '已复制结果' : '复制结果' }}</button></template>
        <div v-else class="text-stats-grid"><div><small>字符数</small><strong>{{ textStats.characters }}</strong></div><div><small>去空格</small><strong>{{ textStats.noSpace }}</strong></div><div><small>行数</small><strong>{{ textStats.lines }}</strong></div><div><small>中文字数</small><strong>{{ textStats.chinese }}</strong></div><div><small>英文单词</small><strong>{{ textStats.words }}</strong></div><div><small>阅读时长</small><strong>{{ textStats.minutes }} 分钟</strong></div></div>
      </div>
    </section>
  </LabToolPage>
</template>

<script setup lang="ts">
import { labTools } from '~/data/lab-tools'
const meta = labTools.find((tool) => tool.id === 'dev')!
const tabs = [{ id: 'json', label: 'JSON' }, { id: 'timestamp', label: '时间戳' }, { id: 'url', label: 'URL' }, { id: 'base64', label: 'Base64' }, { id: 'text', label: '文本统计' }] as const
type TabId = typeof tabs[number]['id']; const activeTab = ref<TabId>('json'); const maxLength = 200000; const copied = ref(false)
const jsonInput = ref('{\n  "hello": "Levi Lab"\n}'); const jsonOutput = ref(''); const jsonError = ref(''); const jsonTooLong = computed(() => jsonInput.value.length > maxLength)
function jsonErrorMessage(error: unknown, input: string) { const message = error instanceof Error ? error.message : 'JSON 语法错误'; const position = Number(message.match(/position (\d+)/i)?.[1]); if (!Number.isFinite(position)) return message; const before = input.slice(0, position); return `JSON 语法错误：第 ${before.split('\n').length} 行，第 ${(before.match(/\n/g)?.length ? position - before.lastIndexOf('\n') : position + 1)} 列附近。` }
function parseJson() { try { return JSON.parse(jsonInput.value) } catch (error) { jsonError.value = jsonErrorMessage(error, jsonInput.value); return undefined } }
function formatJson() { jsonError.value = ''; const parsed = parseJson(); if (parsed !== undefined) jsonOutput.value = JSON.stringify(parsed, null, 2) }
function compactJson() { jsonError.value = ''; const parsed = parseJson(); if (parsed !== undefined) jsonOutput.value = JSON.stringify(parsed) }
const timestampInput = ref(''); const timestampUnit = ref('auto'); const timestampError = ref(''); const timestampResult = reactive({ local: '', utc: '', seconds: '', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || '本地时区' })
function convertTimestamp() { const value = timestampInput.value.trim(); const number = Number(value); const date = value && Number.isFinite(number) ? new Date((timestampUnit.value === 'milliseconds' || (timestampUnit.value === 'auto' && Math.abs(number) > 1e11)) ? number : number * 1000) : new Date(value); if (!value || Number.isNaN(date.getTime())) { timestampError.value = '请输入秒/毫秒时间戳或可识别的日期。'; return }; timestampError.value = ''; timestampResult.local = date.toLocaleString(); timestampResult.utc = date.toISOString(); timestampResult.seconds = String(Math.floor(date.getTime() / 1000)) }
function useNow() { timestampInput.value = String(Date.now()); timestampUnit.value = 'milliseconds'; convertTimestamp() }
const urlInput = ref(''); const urlOutput = ref(''); const urlError = ref(''); const urlParams = ref<{ key: string; value: string }[]>([])
function encodeUrl() { try { urlError.value = ''; urlOutput.value = encodeURIComponent(urlInput.value); urlParams.value = [] } catch { urlError.value = 'URL 编码失败，请检查输入。' } }
function decodeUrl() { try { urlError.value = ''; urlOutput.value = decodeURIComponent(urlInput.value); urlParams.value = [] } catch { urlError.value = 'URL 包含非法的百分号编码，请检查后重试。' } }
function parseUrl() { try { const parsed = new URL(urlInput.value); urlParams.value = [...parsed.searchParams.entries()].map(([key, value]) => ({ key, value })); urlOutput.value = `${parsed.origin}${parsed.pathname}`; urlError.value = urlParams.value.length ? '' : '这个 URL 没有查询参数。' } catch { urlError.value = '请输入完整的 URL，例如 https://example.com/?q=lab。'; urlParams.value = [] } }
const base64Input = ref(''); const base64Output = ref(''); const base64Error = ref('')
function encodeBase64() { try { const bytes = new TextEncoder().encode(base64Input.value); let binary = ''; bytes.forEach((byte) => binary += String.fromCharCode(byte)); base64Output.value = btoa(binary); base64Error.value = '' } catch { base64Error.value = 'Base64 编码失败，请缩短输入后重试。' } }
function decodeBase64() { try { const value = base64Input.value.replace(/\s/g, ''); if (!/^[A-Za-z0-9+/]*={0,2}$/.test(value) || value.length % 4 === 1) throw new Error('invalid'); const binary = atob(value); const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0)); base64Output.value = new TextDecoder().decode(bytes); base64Error.value = '' } catch { base64Error.value = '这不是有效的 Base64 文本。' } }
const textInput = ref(''); const tooLong = computed(() => [jsonInput.value, urlInput.value, base64Input.value, textInput.value].some((value) => value.length > maxLength)); const textStats = computed(() => { const value = textInput.value; const chinese = (value.match(/[\u3400-\u9fff]/g) || []).length; const words = (value.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g) || []).length; return { characters: value.length, noSpace: value.replace(/\s/g, '').length, lines: value ? value.split(/\r?\n/).length : 0, chinese, words, minutes: value ? Math.max(1, Math.ceil((chinese + words) / 350)) : 0 } })
async function copyResult(value: string) { if (!value) return; try { await navigator.clipboard.writeText(value); copied.value = true; window.setTimeout(() => copied.value = false, 1500) } catch { copied.value = false } }
useBlogSeo({ title: '开发者便签', description: '在浏览器本地处理 JSON、时间戳、URL、Base64 和文本统计，不执行、不保存用户输入。', canonical: '/lab/dev', keywords: 'JSON格式化,时间戳转换,URL编码,Base64,文本统计', breadcrumbs: [{ name: '手账实验室', path: '/lab' }, { name: '开发者便签', path: '/lab/dev' }] })
</script>
